def along(a,r,c,dr,dc):
    # return t if a = (r,c)+t*(dr,dc)
    if dr:
        if (a[0]-r)%dr: return None
        t=(a[0]-r)//dr
    else:
        if (a[1]-c)%dc: return None
        t=(a[1]-c)//dc
    if t and (r+dr*t, c+dc*t)==a: return t
    return None
